cpp_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <int BLOCK_SIZE>
__global__ void bn_sum_kernel(const half* __restrict__ input,
                              float* __restrict__ sum,
                              float* __restrict__ sumsq,
                              int N, int C, int H, int W) {
    int c = blockIdx.x;                          // channel index
    int HW = H * W;
    int total = N * HW;                           // elements per channel

    __shared__ float s_data[BLOCK_SIZE];
    __shared__ float ss_data[BLOCK_SIZE];

    float thread_sum = 0.f;
    float thread_sumsq = 0.f;

    for (int idx = threadIdx.x; idx < total; idx += BLOCK_SIZE) {
        int n = idx / HW;
        int hw = idx % HW;
        int offset = ((n * C + c) * H * W) + hw;
        half h = input[offset];
        float v = __half2float(h);
        thread_sum   += v;
        thread_sumsq += v * v;
    }

    s_data[threadIdx.x]   = thread_sum;
    ss_data[threadIdx.x]  = thread_sumsq;
    __syncthreads();

    // reduction in shared memory
    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_data[threadIdx.x]  += s_data[threadIdx.x + stride];
            ss_data[threadIdx.x] += ss_data[threadIdx.x + stride];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        sum[c]   = s_data[0];
        sumsq[c] = ss_data[0];
    }
}

template <int BLOCK_SIZE>
__global__ void bn_norm_kernel(const half* __restrict__ input,
                               half* __restrict__ output,
                               const float* __restrict__ mean,
                               const float* __restrict__ inv_std,
                               int N, int C, int H, int W) {
    int c = blockIdx.x;
    int HW = H * W;
    int total = N * HW;

    for (int idx = threadIdx.x; idx < total; idx += BLOCK_SIZE) {
        int n = idx / HW;
        int hw = idx % HW;
        int offset = ((n * C + c) * H * W) + hw;
        half h = input[offset];
        float v = __half2float(h);
        float norm = (v - mean[c]) * inv_std[c];
        output[offset] = __float2half(norm);
    }
}

// --------------------------------------------------------------------
// Python binding
// --------------------------------------------------------------------
std::vector<torch::Tensor> bn_forward(torch::Tensor input,
                                      torch::Tensor running_mean,
                                      torch::Tensor running_var,
                                      bool training,
                                      float momentum,
                                      float eps) {
    // Expected input: (N, C, H, W), dtype half
    const int N = input.size(0);
    const int C = input.size(1);
    const int H = input.size(2);
    const int W = input.size(3);

    const int BLOCK = 256;
    dim3 grid(C);
    dim3 block(BLOCK);

    auto options_f32 = torch::TensorOptions()
                           .dtype(torch::kFloat32)
                           .device(input.device());

    // temporary buffers for reduction
    torch::Tensor sum   = torch::zeros({C}, options_f32);
    torch::Tensor sumsq = torch::zeros({C}, options_f32);

    // launch reduction kernel
    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "bn_sum_kernel", ([&] {
        bn_sum_kernel<BLOCK><<<grid, block>>>(
            input.data_ptr<half>(),
            sum.data_ptr<float>(),
            sumsq.data_ptr<float>(),
            N, C, H, W);
    }));
    cudaGetLastError();

    // compute mean / variance / inv_std on the GPU (still FP32)
    torch::Tensor elem_cnt = torch::tensor(static_cast<float>(N * H * W),
                                           options_f32);
    torch::Tensor mean = sum / elem_cnt;
    torch::Tensor var  = sumsq / elem_cnt - mean * mean;
    torch::Tensor inv_std = torch::rsqrt(var + eps);

    // update running statistics if in training mode
    if (training) {
        running_mean.mul_(1.0f - momentum).add_(mean, 1.0f - momentum);
        running_var.mul_(1.0f - momentum).add_(var, 1.0f - momentum);
    }

    // allocate output
    torch::Tensor output = torch::empty_like(input);

    // launch normalization kernel
    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "bn_norm_kernel", ([&] {
        bn_norm_kernel<BLOCK><<<grid, block>>>(
            input.data_ptr<half>(),
            output.data_ptr<half>(),
            mean.data_ptr<float>(),
            inv_std.data_ptr<float>(),
            N, C, H, W);
    }));
    cudaGetLastError();

    return {output, mean, var};
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("bn_forward", &bn_forward, "BatchNorm forward (CUDA)");
}
'''

# compile the extension
bn_ext = load_inline(name='bn_ext',
                     cpp_sources=cpp_source,
                     functions=['bn_forward'],
                     verbose=False)

# --------------------------------------------------------------------
# Python wrapper for the custom BatchNorm
# --------------------------------------------------------------------
def _bn_forward(x, running_mean, running_var, training=True,
                momentum=0.1, eps=1e-5):
    out, _, _ = bn_ext.bn_forward(x, running_mean, running_var,
                                  training, momentum, eps)
    return out

# --------------------------------------------------------------------
# Model definition compatible with the reference API
# --------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model using a custom CUDA BatchNorm.
    """
    def __init__(self, num_features: int):
        super().__init__()
        self.num_features = num_features

        # learnable scale (γ) and shift (β) – same defaults as nn.BatchNorm2d
        self.weight = nn.Parameter(torch.ones(num_features,
                                               dtype=torch.float16))
        self.bias   = nn.Parameter(torch.zeros(num_features,
                                               dtype=torch.float16))

        # running statistics (FP32, as in PyTorch)
        self.register_buffer('running_mean',
                             torch.zeros(num_features, dtype=torch.float32))
        self.register_buffer('running_var',
                             torch.ones(num_features, dtype=torch.float32))

        self.momentum = 0.1
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Expect half‑precision input
        if x.dtype != torch.float16:
            x = x.to(torch.float16)

        # Custom CUDA batch‑norm (training mode respects self.training)
        y = _bn_forward(x,
                        self.running_mean,
                        self.running_var,
                        training=self.training,
                        momentum=self.momentum,
                        eps=self.eps)

        # Apply affine transformation (γ and β) – keep in half precision
        y = y * self.weight.view(1, -1, 1, 1) + self.bias.view(1, -1, 1, 1)
        return y

# --------------------------------------------------------------------
# Helper functions to match the reference script
# --------------------------------------------------------------------
def get_inputs():
    batch_size = 64
    features = 64
    dim1 = 512
    dim2 = 512
    x = torch.rand(batch_size, features, dim1, dim2,
                   dtype=torch.float16, device='cuda')
    return [x]

def get_init_inputs():
    return [64]   # number of features
